use super::KernelRule;

pub fn entries() -> Vec<KernelRule> {
    vec![
        // ── L: the shape-preserving-wrongness law — a reshape re-declares
        // bounds over FIXED memory; it cannot permute axes or restore
        // per-axis structure. Relabeling the GEMM product to the documented
        // order keeps the shape and scrambles the values whenever the folded
        // axis exceeds 1 (the N=1 degenerate case makes the two layouts
        // byte-identical, which is what hid the defect for years). The
        // oracle is CONTENT comparison against the per-axis decomposition,
        // never shape equality; the repair is reshape-to-true-layout + an
        // explicit materializing permute; a mask fold carries its structure
        // in a strided multi-axis view end-to-end with a same-shape assert
        // at the seam. ─
        KernelRule {
            rule_id: "reshape-relabel-axis-scramble-content-oracle".to_string(),
            gpu_concept: "MECHANISM (the layout-contract law; category L — conv-as-GEMM layout): a graph-layout operation that only RE-DECLARES dimension bounds (reshape / view / relabel) never moves bytes, so it cannot realize an axis permutation or an axis-structure fold — when the producer's true layout and the consumer's documented layout differ by an axis order, the shape checks all pass and the VALUES are wrong. THE FOUNDING FACE (the conv_1d batch-fold, verbatim from the test header the fix ships): 'conv_1d folds the batch into the rows of the GEMM, so the product is laid out as [OL, N, OC] and reaches the documented [OL, OC, N] only after a transpose of the two slowest dimensions.' The removed wiring was ONE reshape: 'result = ggml_reshape_3d(ctx, result, im2col->ne[1], a->ne[2], im2col->ne[2]); // [N, OC, OL]' — the comment DECLARED the documented shape over memory whose stride structure is [OL, N, OC]; the declared [OL, OC, N] and the actual [OL, N, OC] coincide byte-for-byte at N == 1 (a 1x1 permutation is the identity), which is why every batch-1 caller (whisper-class encoders) was never wrong and the defect survived years of production — at N > 1 every element whose (oc, n) pair is off the diagonal reads another element's value. THE REPAIR IS TWO STEPS, verbatim: 'result = ggml_reshape_3d(ctx, result, im2col->ne[1], im2col->ne[2], a->ne[2]); // [OC, N, OL]' — reshape to the TRUE layout first — then 'result = ggml_cont(ctx, ggml_permute(ctx, result, 0, 2, 1, 3)); // [N, OC, OL]' — an EXPLICIT permute under a materializing cont, the only form that moves the bytes. THE ORACLE (the load-bearing half, verbatim): 'The test runs one batched convolution and N single batch convolutions sharing the same weight and the same input slices, on the CPU backend, and compares every channel of every batch in F32. A wrong layout keeps the shape intact and scrambles the values, so the comparison is on the contents.' — the per-axis DECOMPOSITION (batched vs N singleton runs on shared operands) is the reference; a wrong layout passes every shape assert and fails only content comparison (per-batch NMSE <= 1e-7 against the singleton runs; both paths share the F16 im2col and the same dot products, so only the row count of the GEMM differs). THE SECOND FACE (the mask-fold flatten, #30480, verbatim): a selection carried in mask layout must reach the elementwise fold in that layout — the old wiring flattened 4D to 2D ('sel = ggml_view_2d(...)', 'sel = ggml_add(ctx0, sel, ggml_reshape_2d(ctx0, kq_mask, n_kv, n_tokens));') and the consumer re-expanded with reshape_4d — a flatten/re-expand round trip that only pairs the right elements when BOTH flattenings agree exactly on element order, pitch and padding; the repair carries the selection in the mask layout END-TO-END ('the selection already carries the causal mask, and it comes in the mask layout'): a strided 4D view over the buffer's real row pitch ('const size_t row = sel->nb[2];' — 'row, row*kq_mask->ne[1], row*kq_mask->ne[1]*kq_mask->ne[2], 0') added directly against the 4D mask, with the seam PINNED ('GGML_ASSERT(ggml_are_same_shape(sel, kq_mask));' — the folded carrier and its mask must declare the same shape, plus the count assert 'GGML_ASSERT(n_sel == (int64_t) inp_kpool->n_sel);') so a future producer change refuses loud instead of pairing wrong values under a right shape. THE UNIFIED LAW: shape is NOT layout — every fold that changes what an axis MEANS (permutation, broadcast-structure preservation, batch fold) must either (a) reshape to the true layout and permute with a real copy, or (b) carry the multi-axis structure in strided views end-to-end; and any such fold's test oracle is CONTENT comparison against a decomposition that separates the folded axes, never shape equality or a shared-shape assert alone (the assert is the SEAM guard, the decomposition is the ORACLE — both, not either). REGIME: any graph builder whose producer folds an axis into a GEMM dimension (batch into rows, heads into columns, beams into rows) and whose consumer documents a different axis order; any elementwise fold across a flattened axis that a later consumer re-expands (mask add, bias add, per-axis scale); conv-as-GEMM output finishing is the canonical instance. ANTI-REGIME: layouts where the reshape bounds already match the true stride structure (reshape IS the right op — do not add a permute); consumers that read the product in its true layout (no re-declaration anywhere, nothing to scramble); single-axis folds with no documented order to diverge from. NotBenchable here (no figures ship upstream; the decision content is the contract + the oracle). KINSHIP (do not double-count): ids-path-rebinds-stride-meaning (B198, entries_gpu_66) owns the STRIDE-rebinding hazard — a stride constant that silently names a different quantity once an ids indirection joins (write-bound derivation); THIS owns the AXIS-ORDER hazard — bounds re-declared over memory whose axis order differs (the bytes were always where they are, the labels moved); a wrong stride is an addressing bug, a relabeled axis is a semantics bug, and both hide under green shape checks. repr-align-register-partition-store-forwarding (B211, rust_perf entries_13) is the FAMILY sibling on the codegen face — one layout decision (field alignment) with two downstream costs; THIS is the graph face — one layout contract (axis order) with the shape/values split; the intake staged this as 'the B211 repr-align law's axis-order sibling' and the family read confirms distinct faces, one genus (layout decisions whose correctness is invisible to shape-level checks). dtype-native-source-read-with-shared-admission-predicate (B176, entries_gpu_51) owns the ADMISSION predicate shape — its 'unconditional same-shape assert' hazard arm is the consumer-side half of the mask-face's seam assert; THIS owns the layout carry + the content oracle. zero-pad-ragged-tail (B186-era) pads a tail for staging economics; nothing there re-declares axes. CITE: ggml-org/llama.cpp @ 6868a52 (#28738, MIT) -- ggml/src/ggml.c (the two-step fix in ggml_conv_1d: the true-layout reshape + the permute/cont), tests/test-conv-1d.cpp (the oracle: the header quote, the per-batch NMSE vs N singleton convs on shared weight + input slices, worst batch decides the case, <= 1e-7; the case matrix incl. K=1 pointwise, dilation > 1, OC=1, IC=1, batch larger than every other dimension), AND ggml-org/llama.cpp @ e7268bf (#30480, MIT) -- src/models/glm5-next.cpp build_kpool_select (the n_sel count assert + the strided view_4d carry + the same-shape assert + 'it comes in the mask layout'), src/models/qwen4exp.cpp build_attn_qsa (the same carry on the qsa path: the reshape_4d-and-cb(mask) replaced by assert + cb(sel)), both citing the mask layout in the landed comment. Batch 233 / Plan 235 / Research 264.".to_string(),
            ref_shape: "// naive: the batched conv folds the batch into the GEMM rows, so\n// the product's flat layout is [OL, N, OC] — but the consumer documents\n// [N, OC, OL]. A reshape alone re-declares the bounds and compiles;\n// the shape matches and the values are scrambled for every N > 1\n// (at N == 1 the two layouts are byte-identical, so no batch-1 caller\n// ever sees it).\nfn finish_conv_1d(product: &Tensor, ol: i64, oc: i64, n: i64) -> Tensor {\n    // WRONG: [OL, OC, N] bounds declared over [OL, N, OC] memory.\n    let out = product.reshape_3d(ol, oc, n);\n    // a shape-only test passes here:\n    debug_assert_eq!(out.dims(), [ol, oc, n]);\n    out\n}".to_string(),
            opt_pattern: "// optimized: reshape to the TRUE layout, then permute under a\n// materializing copy -- only a real transpose moves the bytes.\nfn finish_conv_1d(product: &Tensor, ol: i64, oc: i64, n: i64) -> Tensor {\n    let true_layout = product.reshape_3d(ol, n, oc); // [OL, N, OC]\n    let out = true_layout.permute_cont(0, 2, 1); // explicit + cont: the data moves\n    debug_assert_eq!(out.dims(), [ol, oc, n]);\n    out\n}\n\n// THE ORACLE: content, never shape -- one batched run vs N singletons\n// sharing the same weight and the same input slices; a wrong layout\n// keeps the shape intact and scrambles the values.\nfn oracle(w: &Tensor, x: &Tensor, n: usize) -> bool {\n    let y = conv_1d(w, x);\n    for i in 0..n {\n        let xi = x.slice_batch(i);\n    let ref_i = conv_1d(w, &xi);\n        if nmse(y.batch(i), &ref_i) > 1e-7 {\n            return false; // the worst batch decides the case\n        }\n    }\n    true\n}\n\nfn nmse(_y: &Tensor, _r: &Tensor) -> f64 {\n    0.0\n}\n\n// THE MASK-FOLD FACE: carry the selection in the mask layout end-to-end;\n// the seam asserts same-shape, the add runs at the mask's native rank.\nfn fold_sel(sel: &Tensor, kq_mask: &Tensor) -> Tensor {\n    assert!(same_shape(sel, kq_mask));\n    add(sel, kq_mask) // both 4D: the elementwise op pairs per axis\n}\n\nfn same_shape(_a: &Tensor, _b: &Tensor) -> bool {\n    true\n}\n\nfn add(_a: &Tensor, _b: &Tensor) -> Tensor {\n    unimplemented!()\n}\n\nstruct Tensor;\n\nimpl Tensor {\n    fn reshape_3d(&self, _a: i64, _b: i64, _c: i64) -> Tensor {\n        Tensor\n    }\n    fn permute_cont(&self, _p0: usize, _p1: usize, _p2: usize) -> Tensor {\n        Tensor\n    }\n    fn dims(&self) -> [i64; 3] {\n        [0, 0, 0]\n    }\n    fn slice_batch(&self, _i: usize) -> Tensor {\n        Tensor\n    }\n    fn batch(&self, _i: usize) -> Tensor {\n        Tensor\n    }\n}\n\nfn conv_1d(_w: &Tensor, _x: &Tensor) -> Tensor {\n    Tensor\n}".to_string(),
        },
    ]
}
